{
  "description": "The creature is shown in right-facing profile against a plain light background, with a stocky, quadrupedal body entirely covered in dense, shaggy brown fur that is darker on the back and limbs and lighter cream on the chest and belly. It has the overall shape of a bear with a large bear-like head, short rounded ears, a long muzzle with a black nose, four thick pillar-like legs ending in broad clawed paws, and a very short furry tail. Integrated into the fur are numerous glossy, hard, dark brown to black plates resembling beetle exoskeleton, including a large irregular shield over the shoulder and neck, elongated ridged wing-cover-like plates on the flank, smaller triangular and oval plates on the back and rump, and jointed plates encircling the leg joints and ankles, with a row of small dark oval openings along the lower side. A single large, glossy black, upward-curving horn with small side tines projects from the forehead.",
  "parts": [
    {
      "part": "head",
      "looks_like": "bear-like head at the front with a long snout, black nose, dark brown eye, light tan muzzle and lower jaw, and shaggy brown fur on the cheeks and forehead, facing to the right",
      "where": "at the anterior end of the body"
    },
    {
      "part": "horns",
      "looks_like": "single large glossy black curved horn with two small pointed tines on the inner curve, smooth and shiny with a slightly forked tip, resembling a rhinoceros beetle horn",
      "where": "projecting upward and forward from the midline of the forehead just between and slightly in front of the ears"
    },
    {
      "part": "ears",
      "looks_like": "two small rounded furry ears covered in dense brown fur",
      "where": "on top of the head behind the horn, one slightly in front of the other in profile view"
    },
    {
      "part": "legs",
      "looks_like": "four thick, columnar, heavily furred legs with long shaggy brown fur, two forelegs under the chest and two hindlegs under the hips",
      "where": "supporting the body from below, forelegs under the shoulder region and hindlegs under the rump"
    },
    {
      "part": "feet",
      "looks_like": "four large broad paws with dense fur on top and five visible long curved light-colored claws on each, with dark pads underneath",
      "where": "at the distal ends of each leg in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "very short, small, rounded tuft of brown fur barely protruding",
      "where": "at the posterior end of the body on the rump"
    },
    {
      "part": "plates",
      "looks_like": "numerous glossy hard chitinous plates in dark brown and black, including a large irregular shield with a pointed projection on the shoulder, two large elongated ridged elytra-like plates on the mid-flank, smaller triangular, oval and irregular plates on the back, rump and throat, and jointed segmented plates wrapping around the knees, elbows and ankles",
      "where": "embedded in the fur over the dorsal back, lateral sides, shoulder, throat, and encircling the limb joints"
    },
    {
      "part": "markings",
      "looks_like": "dense shaggy fur coloration darker brown on the back, head and outer legs and lighter cream-white on the chest, belly and inner flank, with a row of five small dark oval spiracle-like spots with light rims along the lower flank and additional small dark pits on the throat and shoulder",
      "where": "covering the entire body, with the light area on the ventral chest and belly and the row of spots along the lower lateral side between the front and hind legs"
    }
  ],
  "attached_objects": [],
  "animals": [
    "bear",
    "beetle"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0
}
